def ref(ident,location,section,sm=False):
 sid='v10-'+ident;url='https://www.medicines.org.uk/emc/product/'+location+'/smpc' if sm else 'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid='+location
 sources[sid]=dict(id=sid,title=drugs[ident]['name']+' · selected product renal information',url=url,section=section,type='UK SmPC' if sm else 'Product prescribing information',accessed=DATE);return sid
def mode(ref,rows=None,notes='',status=None,title='Selected adult renal guidance'):
 return dict(status=status or ('summarized' if rows else 'specialist'),tables=[dict(indication=title,rows=[dict(context=c,dose=d) for c,d in rows])] if rows else [],notes=notes,sourceIds=[ref])
def add(ident,location,section,summary,rows=None,notes='',form='Oral',metric='Source-specific renal category; no automatic calculator transfer',flag='monitor',sm=False,status=None,cls=None):
 d=drugs[ident];assert d['entryType']=='catalog',ident;r=ref(ident,location,section,sm)
 d.update(entryType='renal',summary=summary,sourceIds=[r],flag=flag,formulation=form,routes=['Inhaled'] if form.startswith('Inhaled') else ['Oral'],kidneyMetric=metric,updatedInVersion='0.10.0',jurisdiction='Selected adult product information; local authorisation and independent clinical approval remain pending.',completeness='Only the displayed product, route and renal statement are curated. Other formulations, indications and missing RRT prescriptions remain uncurated.',considerations=notes)
 if cls:d['drugClass']=cls
 d['review']['sourceCheckedAt']=DATE;d['modalities']['ckd']=mode(r,rows,notes,status)
 return d
def rrt(d,key,rows=None,notes='',status=None,title='Selected RRT statement'):
 d['modalities'][key]=mode(d['sourceIds'][0],rows,notes,status,title)

