 gap=dict(status='not_reported',value=None,context='No numeric renal half-life curated from the selected label.',sourceIds=[sid])
 removal={k:dict(status='not_curated',value=None,context='No modality-specific removal value curated.',sourceIds=[]) for k in ['ihd','pd','crrt','sled']}
 removal['ihd']=dict(status=hdstatus,value=hd,context='Product-information statement; no modern circuit clearance percentage or post-HD supplement is implied.',sourceIds=[sid])
